/**
 * Super-Resolution Master Report – Frontend Interactivity
 * Consumes global REPORT_CONFIG generated by builder.py
 */

(() => {
    'use strict';

    const config = window.REPORT_CONFIG || { defaultMethod: 'dat2', methods: [], columnFilters: {} };
    const methodMap = new Map(config.methods.map(m => [m.id, m]));

    // Application state
    let currentView = 'comparison';
    let currentMethod = config.defaultMethod || (config.methods[0] && config.methods[0].id) || 'dat2';
    let currentStem = '';
    let isStorefrontTabMode = false;

    // DOM cache
    const dom = {
        body: document.body,
        secComparison: document.getElementById('view-comparison'),
        secStorefront: document.getElementById('view-storefront'),
        subbarComparison: document.getElementById('subbar-comparison'),
        subbarStorefront: document.getElementById('subbar-storefront'),
        modal: document.getElementById('preview-modal'),
        modalTitle: document.getElementById('modal-title'),
        modalStatus: document.getElementById('modal-status'),
        modalImg: document.getElementById('modal-img'),
        modalPhotoFrame: document.getElementById('modal-photo-frame'),
        tabModeBtn: document.getElementById('storefront-tab-mode'),
    };

    // -------------------------------------------------------------------------
    // Main View Switching (Comparison / Storefront / Both)
    // -------------------------------------------------------------------------
    function switchMainView(view) {
        currentView = view;
        document.querySelectorAll('.view-switch-btn').forEach(btn => {
            btn.classList.toggle('active', btn.dataset.view === view);
        });

        const showComp = (view === 'comparison' || view === 'both');
        const showSf = (view === 'storefront' || view === 'both');

        if (dom.secComparison) dom.secComparison.classList.toggle('active', showComp);
        if (dom.secStorefront) dom.secStorefront.classList.toggle('active', showSf);

        if (dom.subbarComparison) dom.subbarComparison.style.display = showComp ? 'flex' : 'none';
        if (dom.subbarStorefront) dom.subbarStorefront.style.display = showSf ? 'flex' : 'none';
    }

    // -------------------------------------------------------------------------
    // Studio Photo Background Tone (CSS Multiply blending)
    // -------------------------------------------------------------------------
    function setPhotoTone(tone) {
        dom.body.classList.remove('tone-grey-soft', 'tone-grey-medium', 'tone-grey-warm', 'tone-white');
        dom.body.classList.add('tone-' + tone);

        document.querySelectorAll('[data-tone]').forEach(btn => {
            btn.classList.toggle('active', btn.dataset.tone === tone);
        });
    }

    function getCurrentTone() {
        const tones = ['grey-soft', 'grey-medium', 'grey-warm', 'white'];
        for (const t of tones) {
            if (dom.body.classList.contains('tone-' + t)) return t;
        }
        return 'grey-soft';
    }

    // -------------------------------------------------------------------------
    // Aspect Ratio & Column Grid Presets
    // -------------------------------------------------------------------------
    function setCropRatio(ratio) {
        dom.body.classList.remove('crop-3-5', 'crop-9-16', 'crop-3-4', 'crop-1-1');
        dom.body.classList.add('crop-' + ratio);

        document.querySelectorAll('[data-crop]').forEach(btn => {
            btn.classList.toggle('active', btn.dataset.crop === ratio);
        });
    }

    function setColumns(cols) {
        dom.body.classList.remove('cols-8', 'cols-6', 'cols-4', 'cols-3', 'cols-2');
        dom.body.classList.add('cols-' + cols);

        document.querySelectorAll('[data-cols]').forEach(btn => {
            btn.classList.toggle('active', btn.dataset.cols === cols);
        });
    }

    // -------------------------------------------------------------------------
    // Comparison Column Filters
    // -------------------------------------------------------------------------
    function setColumnFilter(filterId) {
        document.querySelectorAll('[data-filter]').forEach(btn => {
            btn.classList.toggle('active', btn.dataset.filter === filterId);
        });

        const allowed = config.columnFilters[filterId] || [];
        const filterActive = allowed.length > 0;

        document.querySelectorAll('.comparison-grid .thumb').forEach(thumb => {
            if (!filterActive) {
                thumb.classList.remove('hidden');
            } else {
                const methodId = thumb.dataset.method;
                thumb.classList.toggle('hidden', !allowed.includes(methodId));
            }
        });
    }

    // -------------------------------------------------------------------------
    // Storefront Tab Mode
    // -------------------------------------------------------------------------
    function toggleStorefrontTabMode() {
        isStorefrontTabMode = !isStorefrontTabMode;
        dom.body.classList.toggle('storefront-tab-mode', isStorefrontTabMode);

        if (dom.tabModeBtn) {
            dom.tabModeBtn.classList.toggle('active', isStorefrontTabMode);
            dom.tabModeBtn.textContent = isStorefrontTabMode
                ? '📑 Włączony tryb zakładek w miejscu (kliknij metodę powyżej)'
                : '🔄 Przełącz tryb: Zakładki w miejscu';
        }

        if (isStorefrontTabMode) {
            selectStorefrontTab('dat2');
        }
    }

    function selectStorefrontTab(methodId) {
        if (!isStorefrontTabMode) return;
        document.querySelectorAll('.storefront-section').forEach(sec => {
            sec.classList.remove('active-tab');
        });
        const target = document.getElementById('storefront-' + methodId);
        if (target) {
            target.classList.add('active-tab');
            window.scrollTo({ top: 120, behavior: 'instant' });
        }
    }

    // -------------------------------------------------------------------------
    // Lightbox Modal
    // -------------------------------------------------------------------------
    function openModal(stem, methodId, title) {
        currentStem = stem;
        currentMethod = methodMap.has(methodId) ? methodId : (config.defaultMethod || 'dat2');

        if (dom.modalTitle) {
            dom.modalTitle.textContent = title || 'Podgląd HD';
        }

        updateModalView();

        const activeTone = getCurrentTone();
        document.querySelectorAll('.modal-tones [data-tone]').forEach(btn => {
            btn.classList.toggle('active', btn.dataset.tone === activeTone);
        });

        if (dom.modal) dom.modal.classList.add('open');
    }

    function switchModalMethod(methodId) {
        if (!methodMap.has(methodId)) return;
        currentMethod = methodId;
        updateModalView();
    }

    function updateModalView() {
        const info = methodMap.get(currentMethod);
        if (!info) return;

        if (dom.modalImg) {
            dom.modalImg.src = `${info.imageDir}/${currentStem}.${info.extension}`;
            dom.modalImg.alt = info.label;
        }

        if (dom.modalPhotoFrame) {
            dom.modalPhotoFrame.classList.toggle('is-pixelated', Boolean(info.pixelated));
        }

        document.querySelectorAll('[data-modal-method]').forEach(btn => {
            btn.classList.toggle('active', btn.dataset.modalMethod === currentMethod);
        });

        if (dom.modalStatus) {
            dom.modalStatus.textContent = 'Aktywna metoda podglądu HD: ' + info.label;
        }
    }

    function closeModal() {
        if (dom.modal) dom.modal.classList.remove('open');
    }

    // -------------------------------------------------------------------------
    // Global Event Delegation
    // -------------------------------------------------------------------------
    document.addEventListener('click', (event) => {
        const target = event.target;

        // View switch
        const viewBtn = target.closest('[data-view]');
        if (viewBtn) {
            switchMainView(viewBtn.dataset.view);
            return;
        }

        // Photo tone switch
        const toneBtn = target.closest('[data-tone]');
        if (toneBtn) {
            setPhotoTone(toneBtn.dataset.tone);
            return;
        }

        // Aspect ratio switch
        const cropBtn = target.closest('[data-crop]');
        if (cropBtn) {
            setCropRatio(cropBtn.dataset.crop);
            return;
        }

        // Columns switch
        const colsBtn = target.closest('[data-cols]');
        if (colsBtn) {
            setColumns(colsBtn.dataset.cols);
            return;
        }

        // Column filter
        const filterBtn = target.closest('[data-filter]');
        if (filterBtn) {
            setColumnFilter(filterBtn.dataset.filter);
            return;
        }

        // Storefront tab toggle
        if (target.closest('#storefront-tab-mode')) {
            toggleStorefrontTabMode();
            return;
        }

        // Storefront section anchor (tab mode handler)
        const sfNavBtn = target.closest('[data-storefront-section]');
        if (sfNavBtn && isStorefrontTabMode) {
            event.preventDefault();
            selectStorefrontTab(sfNavBtn.dataset.storefrontSection);
            return;
        }

        // Modal method tab
        const modalTabBtn = target.closest('[data-modal-method]');
        if (modalTabBtn) {
            switchModalMethod(modalTabBtn.dataset.modalMethod);
            return;
        }

        // Modal close button
        if (target.closest('[data-close-modal]')) {
            closeModal();
            return;
        }

        // Modal backdrop click
        if (target === dom.modal) {
            closeModal();
            return;
        }

        // Card / thumbnail click -> open preview modal
        const previewTrigger = target.closest('[data-preview]');
        if (previewTrigger) {
            const stem = previewTrigger.dataset.stem;
            const methodId = previewTrigger.dataset.method || currentMethod;
            const title = previewTrigger.dataset.title;
            if (stem) {
                openModal(stem, methodId, title);
            }
        }
    });

    // Keyboard shortcuts: Esc to close modal, 1..N to switch methods
    document.addEventListener('keydown', (event) => {
        if (!dom.modal || !dom.modal.classList.contains('open')) return;

        if (event.key === 'Escape') {
            closeModal();
            return;
        }

        const digit = parseInt(event.key, 10);
        if (digit >= 1 && digit <= config.methods.length) {
            const selected = config.methods[digit - 1];
            if (selected) switchModalMethod(selected.id);
        }
    });

})();
